"""Product-specific renal instructions and explicit institutional PD schedules.

Current SPLs were retrieved directly from the official DailyMed API. Original
historical PK fields are retained; selected current IHD facts have their own source.
"""
from pathlib import Path
import json
R=Path(__file__).parent;D=R/'dist';DATE='2026-10-30';VERSION='0.11.1'
data=json.loads((D/'database.json').read_text());assert data['version']=='0.11.0'
drugs={d['id']:d for d in data['drugs']};old=json.loads(json.dumps(drugs));sources={s['id']:s for s in data['sources']}
labels=json.loads((R/'label_sources_v111.json').read_text())
for key,s in labels.items():
 sid='spl111-'+s['drugId'];sources[sid]=dict(id=sid,title='DailyMed · '+s['title'],url='https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid='+s['setid'],section='Selected adult renal instructions; dosage, renal-use and PK sections. Product-specific limitations apply.',type='US product label / official SPL',accessed=DATE,labelVersion=s['spl_version'],labelPublishedDate=s['published_date'],retrievalUrl=s['retrievalUrl'],xmlSha256=s['xmlSha256'])
def table(indication,rows):return dict(indication=indication,rows=[dict(context=c,dose=v) for c,v in rows])
def mode(ident,key,indication=None,rows=None,notes='',status='summarized',refs=None):
 drugs[ident]['modalities'][key]=dict(status=status,tables=[table(indication,rows)] if rows else [],notes=notes,sourceIds=refs or ['spl111-'+ident])
def new(ident,formulation,metric,summary,notes,rows=None,indication='Selected adult renal instructions',status='summarized',flag='adjust'):
 d=drugs[ident];assert d['entryType']=='catalog',ident
 d.update(entryType='renal',formulation=formulation,kidneyMetric=metric,summary=summary,considerations=notes,sourceIds=['spl111-'+ident],flag=flag,jurisdiction='Selected US product label; check local authorisation, exact formulation and indication.',completeness='Selected renal instructions only. Missing modality schedules, interactions and full monographs remain incomplete; independent clinical approval pending.',updatedInVersion=VERSION)
 d['review']['sourceCheckedAt']=DATE
 d['routes']=['Parenteral'] if formulation.startswith(('Injection','IV')) else ['Oral','Parenteral'] if ' / IV' in formulation else ['Transdermal'] if formulation.startswith('Transdermal') else ['Oral']
 mode(ident,'ckd',indication,rows,notes,status)
 p=d['pharmacokinetics']
 if p['status']=='source_summary':p['notes']='Historical reference PK fields retained from 2018. Renal instructions above now use a separately cited US product label; any updated IHD field identifies its own label evidence. '+p['notes'].split('verification. ')[-1]
 return d
GEN='Renal impairment · no numeric cutoff in selected label'
opioids=[
 ('morphine','Injection · selected morphine sulfate product','Use a lower starting dose and titrate slowly.','Morphine injection label §8.7: renal failure changes disposition. Monitor sedation, respiratory depression and hypotension. Active-metabolite accumulation matters; no fixed percentage, oral/ER conversion or dialysis supplement is selected.','Start below the usual dose; increase slowly to response'),
 ('hydromorphone','Oral immediate-release tablets / solution','Start at one-quarter to one-half of the usual starting dose.','Dilaudid oral label §§2.5/8.7. Select the fraction according to severity and monitor closely during titration. This is a starting-dose reduction, not a universal maintenance dose or IV/ER conversion.','Begin with 25–50% of the usual starting dose, according to renal impairment'),
 ('oxycodone','Oral immediate-release ROXICODONE tablets','Use a lower initial dose and careful titration.','Selected IR label §8.7: clearance may fall in renal impairment. Monitor respiration, sedation and hypotension. No numerical fraction or ER/combination-product regimen is specified.','Begin below the usual starting dose and titrate carefully'),
 ('fentanyl','Injection · selected fentanyl citrate product','Use cautiously and reduce the dose as needed.','Injection label §8.7. Monitor respiration, sedation and hypotension. This instruction does not apply automatically to patches, transmucosal products or opioid conversions.','Reduce the injection dose as needed; titrate under monitored care'),
 ('codeine','Oral codeine sulfate tablets','Lower doses or longer intervals are required in renal failure.','Selected label §8.7 warns of reduced clearance and metabolite accumulation. Monitor respiration, sedation and hypotension. No numeric safe dose or dialysis supplement is established here.','Start below the usual dose or lengthen the interval; titrate slowly'),
 ('pethidine-meperidine','Injection · DEMEROL meperidine','Renal impairment can cause parent and normeperidine accumulation.','Selected label §8.7 requires cautious, slow titration and close CNS/respiratory monitoring. No numeric renal or dialysis regimen is supplied. The warning is not evidence of renal safety.','Use cautiously; titrate slowly and monitor closely'),
 ('methadone','Oral selected methadone hydrochloride tablets','Use lower initial doses, longer intervals and slow titration.','Selected label §8.7: renal pharmacokinetics are not extensively evaluated. Monitor CNS and respiratory depression. Pain and opioid-use-disorder protocols differ; no conversion or fixed renal dose is calculated.','Begin with a lower dose and longer interval; increase slowly')]
for ident,form,summary,note,dose in opioids:new(ident,form,GEN,summary,note,[(GEN,dose)],flag='monitor')
new('buprenorphine','Transdermal BUTRANS patch','No validated CrCl dose algorithm in selected patch label','BUTRANS has no dedicated renal-impairment study.','Selected label §12.3 describes similar IV exposure in renal failure and a separate non-US patch HD study, not a validated BUTRANS dialysis regimen. Do not import the study patch strength or a sublingual/opioid-use-disorder conversion.',status='insufficient_data',flag='monitor')
new('lacosamide','Oral VIMPAT / IV','Adult Cockcroft–Gault CrCl · mL/min','Reduce the maximum by 25% below CrCl 30 or in ESRD.','Selected label §§2.1/2.4/8.6: adult usual maximum is 400 mg/day, so the renal maximum is 300 mg/day. Individualise initiation and titration. Strong CYP3A4/CYP2C9 inhibitors can require further reduction. This is maintenance guidance, not an emergency loading protocol.',[('CrCl ≥30','No renal reduction; use the indication-specific regimen'),('CrCl <30 or ESRD','Maximum 300 mg/day (75% of the usual 400 mg/day adult maximum)')])
mode('lacosamide','ihd','Adult VIMPAT · 4-hour HD',[('Maintenance','Apply the ESRD maximum of 300 mg/day'),('After 4-hour HD','Consider an additional dose of up to 50%; individualise the supplement')],'Label §2.4 does not select a universal fixed milligram supplement. Review seizure control, treatment duration and interacting medicines.')
new('lamotrigine','Oral immediate-release LAMICTAL products','Significant renal impairment · no single CrCl cutoff in label','Reduced maintenance doses may suffice; preserve interaction-based titration.','Label §§2.1/8.7: initial titration depends on concomitant antiseizure medicines. Severe renal experience is limited. Do not replace the slow rash-prevention titration with a flat renal percentage.',[('Significant renal impairment','Select initial titration from the concomitant-drug schedule; a lower maintenance dose may be effective')],flag='monitor')
mode('lamotrigine','ihd',notes='Label §12.3 reports about 20% removal in a 4-hour study, but gives no fixed maintenance or post-HD supplement. Individualise with neurology/pharmacy.',status='specialist')
new('oxcarbazepine','Oral TRILEPTAL immediate-release tablets / suspension','CrCl · mL/min','Below CrCl 30, start at half the usual initial dose.','Label §2.7: 300 mg/day TOTAL, divided twice daily, then increase slowly. This is not 300 mg twice daily. Monitor sodium and tolerability; no dialysis regimen or ER conversion is assigned.',[('CrCl <30','Initial total 300 mg/day in two divided doses (150 mg twice daily); titrate slowly')])
new('topiramate','Oral TOPAMAX tablets / sprinkle capsules','Label indexed CrCl · mL/min/1.73 m²','Below indexed CrCl 70, use half the usual adult dose.','Label §§2.5/2.6: the threshold is indexed CrCl as printed, not the calculator eGFR automatically. Match indication and titration; monitor bicarbonate and stone risk. No fixed dialysis supplement is given.',[('CrCl <70 mL/min/1.73 m²','Use 50% of the usual adult dose for the intended indication')])
mode('topiramate','ihd',notes='A supplemental dose may be needed. Label §2.6 requires the duration and clearance of dialysis and the patient’s residual renal clearance to determine the adjustment; no universal percentage is supplied.',status='specialist')
new('phenytoin','Oral extended phenytoin sodium DILANTIN capsules','Renal disease / hypoalbuminaemia · unbound concentration','Base monitoring on unbound phenytoin, not total concentration alone.','Selected ER capsule label §§2.1/2.5/8.6: do not use its oral loading regimen in patients with a history of renal disease. Free fraction rises in renal disease; individualise maintenance by clinical response and measured unbound levels. Formulations differ.',[('Renal disease / hypoalbuminaemia','Individualise maintenance using the unbound concentration; label reference 1–2 micrograms/mL')],flag='monitor')
new('valproate','Oral valproic acid solution · selected product','Renal failure · source CrCl <10 mL/min','The label does not require a routine renal dose reduction.','Selected valproic acid label §12.3: reduced binding makes total concentrations misleading. Individualise with clinical assessment and unbound exposure where available; do not extend this to all formulations or poisoning treatment.',[('Renal failure, including source CrCl <10','No routine renal dose reduction appears necessary in this label; monitor clinical response and unbound exposure')],flag='monitor')
mode('valproate','ihd','Selected valproic acid label · therapeutic use',[('Renal failure / HD','No routine renal reduction appears necessary; individualise monitoring')],'Label §12.3 reports about 20% reduction in concentration by HD. No fixed post-HD supplement is selected. Overdose has different unbound fractions and removal.')
new('pramipexole','Oral immediate-release pramipexole dihydrochloride tablets','CrCl · mL/min','IR Parkinson’s doses depend on CrCl; RLS uses slower titration.','Label §2.2 doses are expressed for the US dihydrochloride product; do not substitute the historical handbook’s 88-microgram base strengths. RLS and Parkinson’s regimens are separate. ER products are excluded.',[('CrCl >50 · Parkinson’s','Start 0.125 mg three times daily; maximum 1.5 mg three times daily'),('CrCl 30–50 · Parkinson’s','Start 0.125 mg twice daily; maximum 0.75 mg three times daily'),('CrCl 15 to <30 · Parkinson’s','Start 0.125 mg once daily; maximum 1.5 mg once daily'),('CrCl <15','Insufficiently studied; no regimen selected'),('RLS with CrCl 20–60','Start 0.125 mg once daily 2–3 h before bed; allow 14 days between titration steps (label §2.3)')])
